edit("android/app/src/main/java/com/metallic/chiaki/stream/VideoRenderer.kt", "                outColor = vec4(texture(u_Texture,vec2(uv.x,1.0-uv.y)).rgb,1.0);", "                vec2 src=vec2(uv.x,1.0-uv.y);\n                vec2 local=(src-u_Crop.xy)/max(u_Crop.zw-u_Crop.xy,vec2(.0001));\n                if (u_DepthReady > .001 && all(greaterThanEqual(local,vec2(0.))) && all(lessThanEqual(local,vec2(1.)))) {\n                    vec2 d=texture(u_Shift,local).rg;\n                    bool left=(v_TexCoord.x < .5) != (u_Swap > .5);\n                    src.x += ((left ? d.r : d.g)-128.0/255.0)*.16*(u_Crop.z-u_Crop.x)*u_DepthReady;\n                }\n                // Fused, bounded-cost spatial enhancement. No intermediate upscale framebuffer.\n                vec3 c=sampleGame(src);\n                vec3 a=sampleGame(src-u_Texel);\n                vec3 b=sampleGame(src+u_Texel);\n                vec3 lo=min(c,min(a,b)), hi=max(c,max(a,b));\n                vec3 enhanced=c+.12*(2.*c-a-b);\n                outColor=vec4(clamp(enhanced,max(vec3(0.),lo-.025),min(vec3(1.),hi+.025)),1.);\n")
edit("android/app/src/main/java/com/metallic/chiaki/stream/VideoRenderer.kt", "    private var psvrProgram: Program? = null", "    private var psvrProgram: Program? = null\n    var depthContext: Context? = null\n    private val depthBusy = java.util.concurrent.atomic.AtomicBoolean(false)\n    private val depthWorker = java.util.concurrent.Executors.newSingleThreadExecutor { task ->\n        Thread(task,\"VCVR-depth\").apply { priority=Thread.MIN_PRIORITY }\n    }\n    @Volatile private var depthEngine: Depth? = null\n    @Volatile private var depthFailed=false\n    @Volatile private var depthClosed=false\n    @Volatile private var nextDepthMs=0L\n    private var depthTarget: RenderTarget?=null\n    private var depthPixels: ByteBuffer?=null\n    private var shiftPixels: ByteBuffer?=null\n    private var shiftTexture=0\n    private var lastDepthUpload=0L\n    private var lastThermalCheck=0L\n    private var thermalLevel=0\n    private val depthCrop=floatArrayOf(0f,0f,1f,1f)\n\n    private fun prepareDepth() {\n        if (depthContext==null) return\n        depthTarget=createRenderTarget(Depth.RW,Depth.RH)\n        if(depthPixels==null) depthPixels=ByteBuffer.allocateDirect(Depth.RW*Depth.RH*4)\n        if(shiftPixels==null) shiftPixels=ByteBuffer.allocateDirect(Depth.W*Depth.H*2)\n        val ids=IntArray(1)\n        GLES30.glGenTextures(1,ids,0); shiftTexture=ids[0]\n        GLES30.glBindTexture(GLES30.GL_TEXTURE_2D,shiftTexture)\n        GLES30.glTexImage2D(GLES30.GL_TEXTURE_2D,0,GLES30.GL_RG8,Depth.W,Depth.H,0,GLES30.GL_RG,GLES30.GL_UNSIGNED_BYTE,null)\n        GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D,GLES30.GL_TEXTURE_MIN_FILTER,GLES30.GL_LINEAR)\n        GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D,GLES30.GL_TEXTURE_MAG_FILTER,GLES30.GL_LINEAR)\n        GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D,GLES30.GL_TEXTURE_WRAP_S,GLES30.GL_CLAMP_TO_EDGE)\n        GLES30.glTexParameteri(GLES30.GL_TEXTURE_2D,GLES30.GL_TEXTURE_WRAP_T,GLES30.GL_CLAMP_TO_EDGE)\n        lastDepthUpload=0L\n    }\n\n    private fun updateDepth(hasFrame:Boolean) {\n        val ctx=depthContext ?: return\n        val target=depthTarget ?: return\n        val pixels=depthPixels ?: return\n        val upload=shiftPixels ?: return\n        val now=android.os.SystemClock.elapsedRealtime()\n        if(now-lastThermalCheck>=1000L) {\n            lastThermalCheck=now\n            if(android.os.Build.VERSION.SDK_INT>=29) {\n                thermalLevel=ctx.getSystemService(android.os.PowerManager::class.java)?.currentThermalStatus ?: 0\n            }\n        }\n        val d=depthEngine\n        if(d!=null && d.fresh) {\n            synchronized(d) {\n                upload.clear(); upload.put(d.shift); upload.flip()\n                d.crop.copyInto(depthCrop); d.fresh=false\n            }\n            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D,shiftTexture)\n            GLES30.glTexSubImage2D(GLES30.GL_TEXTURE_2D,0,0,0,Depth.W,Depth.H,GLES30.GL_RG,GLES30.GL_UNSIGNED_BYTE,upload)\n            lastDepthUpload=now\n        }\n        if(!hasFrame || depthFailed || depthClosed || thermalLevel>=3 || now<nextDepthMs || !depthBusy.compareAndSet(false,true)) return\n        try {\n            // Only a tiny downsample is copied/read back, never the full game frame.\n            drawPass(copyProgram,target.fboId,Depth.RW,Depth.RH,GLES11Ext.GL_TEXTURE_EXTERNAL_OES,oesTextureId) {\n                GLES30.glUniformMatrix4fv(uCopySTMatrixLoc,1,false,stMatrix,0)\n            }\n            pixels.clear()\n            GLES30.glReadPixels(0,0,Depth.RW,Depth.RH,GLES30.GL_RGBA,GLES30.GL_UNSIGNED_BYTE,pixels)\n            GLES30.glBindFramebuffer(GLES30.GL_FRAMEBUFFER,0)\n            depthWorker.execute {\n                val start=android.os.SystemClock.elapsedRealtime()\n                try {\n                    android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND)\n                    val engine=depthEngine ?: Depth(ctx.assets.open(\"depth.onnx\").use { it.readBytes() },1).also { depthEngine=it }\n                    engine.load(pixels)\n                    engine.process(.022f,.5f,.9f)\n                } catch(error:Exception) {\n                    depthFailed=true; Log.e(TAG,\"Neural stereo unavailable\",error)\n                } catch(error:LinkageError) {\n                    depthFailed=true; Log.e(TAG,\"Neural runtime unavailable\",error)\n                } finally {\n                    val end=android.os.SystemClock.elapsedRealtime()\n                    // At most 25% inference duty cycle, max 2 Hz, one job in flight.\n                    nextDepthMs=end+maxOf(500L,(end-start)*3L)\n                    depthBusy.set(false)\n                }\n            }\n        } catch(error:RuntimeException) {\n            depthBusy.set(false); depthFailed=true; Log.e(TAG,\"Depth readback unavailable\",error)\n        }\n    }")
